// === Tab: mySketch ===
let palette = [];
let graphics;

function setup() {
	createCanvas(800, 800);
	colorMode(HSB, 360, 100, 100, 100);
	strokeJoin(ROUND);

	palette = shuffle(random(colorScheme).colors.concat());

	frameRate(1 / 2);

	graphics = createGraphics(width, height);

	for (let i = 0; i < (graphics.width * graphics.height * 10) / 100; i++) {
		let x = random(graphics.width);
		let y = random(random()) * graphics.height * 1.5 - graphics.height * 0.15;
		graphics.stroke(255, map(y, 0, height, 5, 5) / 4);
		graphics.strokeWeight(map(y, 0, height, 1, 3));
		graphics.point(x, y);
	}
}

function draw() {
	setup();

	noiseSeed(random(10000))
	background(220, 80, 70);
	let gradient = drawingContext.createLinearGradient(0, 0, 0, height);

	noStroke();
	gradient.addColorStop(0, color(220, 80, 0));
	gradient.addColorStop(0.4, color(220, 80, 70));

	drawingContext.fillStyle = gradient;
	rect(0, 0, width, height);

	// stroke(0,0,30);
	let w = height / 10 / 1.5;
	let h = height * 2;
	let yStep;
	for (let y = height / 4; y < height; y += (Math.max(0.001, Math.abs(yStep)) || 1)) {
		yStep = map(y, height / 4, height, height / 50, height / 20);
		let xStep;
		let xStepBase = map(y, height / 4, height, w / 2, w * 3);
		let ny;
		for (let x = 0; x < width; x += (Math.max(0.001, Math.abs(xStep)) || 1)) {
			ny = noise(x / width) * height / 2;
			xStep = random(xStepBase / 2, xStepBase * 2);
			let hStep =
				map(y, height / 4, height, height / 100, height / 10) *
				(random() > 0.5 ? -1 : 1);
			drawHouse(x, y + hStep + ny, xStep, h, palette);
		}
		blendMode(ADD);
		image(graphics, 0, 0);
		blendMode(MULTIPLY);
		gradient = drawingContext.createLinearGradient(0, y, 0, height);
		gradient.addColorStop(1, color(0, 0, 0, 1));
		gradient.addColorStop(0, color(0, 0, 0, 0));
		drawingContext.fillStyle = gradient;

		// rect(0, 0, width, height);
		blendMode(BLEND);
	}
	graphics.remove();
	// noLoop();
}

function drawHouse(x, y, w, h, palette, isStroke) {
	let colors = shuffle(palette.concat());
	let w2 = random(w / 8, w / 2);
	let bool = random() > 0.5;

	push();
	translate(x, y);
	if (bool) {
		translate(w, 0);
		scale(-1, 1);
	}
	let scl = random(0.75, 1.25);
	scale(scl, 1);
	strokeWeight(1 / scl);
	if (isStroke) {
		stroke(0, 0, 0);
	} else {
		noStroke();
	}


	push();
	drawingContext.shadowColor = color(0, 0, 0, 33);
	drawingContext.shadowBlur = w / 3;

	drawingContext.shadowOffsetX = w / 4 / 2;
	if (random(100) > 50) {
		let c = colors[colors.length - 1];
		c = color(hue(window.color(c)), saturation(window.color(c)), max(brightness(window.color(c)) - 20, 0));
		fill(c);
		rect(w / 2, -random(w / 3, w / 8), random(w / 15, w / 10), h);
	}

	fill(0, 0, 100);


	beginShape();
	vertex(0, w2);
	vertex(w / 2 / 2, 0);
	vertex((w * 3) / 4, 0);
	vertex(w, w2);
	vertex(w, h);
	vertex(0, h);
	endShape(CLOSE);
	drawingContext.shadowBlur = 0;
	pop();
	let c1 = colors[0];
	let c2 = color(
		hue(window.color(c1)),
		saturation(window.color(c1)),
		constrain(brightness(window.color(c1)) - 20, 0, 100)
	);
	let gradient = drawingContext.createLinearGradient(0, 0, 0, w2);
	gradient.addColorStop(0, c1);
	gradient.addColorStop(1, c2);
	drawingContext.fillStyle = gradient;

	beginShape();
	vertex(w / 2 / 2, 0);
	vertex((w * 3) / 4, 0);
	vertex(w, w2);
	vertex(w / 2, w2);
	endShape(CLOSE);

	c1 = colors[1];
	c2 = color(hue(window.color(c1)), saturation(window.color(c1)), constrain(brightness(window.color(c1)) - 20, 0, 100));
	gradient = drawingContext.createLinearGradient(0, w2, 0, h);
	gradient.addColorStop(0, c1);
	gradient.addColorStop(1 / 10, c2);
	drawingContext.fillStyle = gradient;

	beginShape();
	vertex(w / 2, w2);
	vertex(w, w2);
	vertex(w, h);
	vertex(w / 2, h);
	endShape(CLOSE);

	c1 = colors[2];
	c2 = colors[3]; //color(hue(window.color(c1)), saturation(window.color(c1)), constrain(brightness(window.color(c1)) - 30, 0, 100));
	gradient = drawingContext.createLinearGradient(0, 0, 0, h);
	gradient.addColorStop(0, c1);
	gradient.addColorStop(1 / 15, c2);
	drawingContext.fillStyle = gradient;

	beginShape();
	vertex(0, w2);
	vertex(w / 2 / 2, 0);
	vertex(w / 2, w2);
	vertex(w / 2, h);
	vertex(0, h);
	endShape(CLOSE);

	let isWindow = random() > 0.5;

	push();
	fill(colors[colors.length - 2]);
	translate(random() > 0.5 ? 0 : w / 2, w2);
	rectMode(CENTER);
	let h2 = (w / 2) * random(1 / 2, 1);
	translate(w / 2 / 2, h2);
	rect(0, 0, w / 2 / 2, h2);
	drawingContext.clip();
	translate(-w / 2 / 2 / 2, -h2 / 2);
	drawingContext.shadowColor = color(colors[colors.length - 1]);
	drawingContext.shadowBlur = w;
	drawingContext.shadowOffsetX = w / 4;
	drawingContext.shadowOffsetX = w / 4;
	// blendMode(BURN);
	fill(random(colors));
	for (let i = 0; i < 10; i++) {
		circle(-w / 4, -w / 4, w / 2);
	}
	pop();

	pop();
}

